//! Real Runtime -> Cells/Luau -> Host -> workspace/data/archive capabilities
//! for the preset capability groups: atomic writes and change batches, bounded
//! search and code reads, and pure data/archive operations.
//!
//! Every case starts from the Host the Runtime actually opened. No library
//! executor is called directly. Dynamic change-batch arguments (`batch_id` is
//! generated by prepare) are supplied to a later Runtime as exact grants; the
//! tests never use a wildcard or prefix permission.
use cayw_ai::{AssistantEvent, AssistantStream, CancellationToken, Model, ModelRequest, Provider};
use cayw_core::{
    ApprovalRequest, CapabilityCallRecord, CapabilityOutcome, CapabilityReconciliation,
    CapabilityStage, CoreEvent, SessionState,
};
use cayw_runtime::{
    ApprovalChoice, Runtime, RuntimeConfig, RuntimeError, ScopedPermission, SessionView, TaskState,
};
use futures::stream;
use serde_json::{Value, json};
use std::{path::Path, sync::Arc, time::Duration};

const HASH_ONE: &str = "7692c3ad3540bb803c020b3aee66cd8887123234ea0c6e7143c0add73ff431ed";
const HASH_TWO: &str = "3fc4ccfe745870e2c0d99f71f30ff0656c8dedd41cc1d7d3d376b0dbe685e2f3";
const HASH_THREE: &str = "8b5b9db0c13db24256c829aa364aa90c6d2eba318b9232a4ab9313b954d3555f";
const HASH_EXISTING_ONE: &str = "6b86b273ff34fce19d6b804eff5a3f5747ada4eaa22f1d49c01e52ddb7875b4b";
const SHA256_ABC: &str = "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad";
const BLAKE3_ABC: &str = "6437b3ac38465133ffb63b75273a8db548c558465d79db03fd359c6cd5bd9d85";
const TAR_BODY: &str = "hello tar\n";

/// Installed only after this fixture inspects the original batch journal and
/// workspace bytes. A caller cannot change the actor, origin or decided result.
struct InspectedBatchReceipt(CapabilityReconciliation);
impl cayw_core::ReconciliationVerifier for InspectedBatchReceipt {
    fn verify(&self, request: &cayw_core::ReconciliationRequest) -> Result<(), String> {
        match request {
            cayw_core::ReconciliationRequest::Capability { reconciliation }
                if reconciliation == &self.0 && reconciliation.actor == "fixture-host" =>
            {
                Ok(())
            }
            _ => Err("request differs from the inspected original change-batch receipt".into()),
        }
    }
}

struct Script(String);
impl Provider for Script {
    fn stream(&self, request: ModelRequest, _: CancellationToken) -> AssistantStream {
        let message = cayw_runtime::fixture::script_response(
            &request,
            &self.0,
            &format!("preset-{}", request.messages.len()),
        );
        Box::pin(stream::iter([AssistantEvent::Done { message }]))
    }
}

fn setup() -> tempfile::TempDir {
    let temp = tempfile::tempdir().unwrap();
    std::fs::create_dir(temp.path().join("workspace")).unwrap();
    temp
}
fn config() -> RuntimeConfig {
    RuntimeConfig {
        max_run_time: Duration::from_secs(30),
        ..Default::default()
    }
}
fn allow(config: &mut RuntimeConfig, name: &str, args: Value) {
    config.permissions.push(ScopedPermission::exact(name, args));
}
fn write(root: &Path, path: &str, bytes: &[u8]) {
    let full = root.join(path);
    if let Some(parent) = full.parent() {
        std::fs::create_dir_all(parent).unwrap();
    }
    std::fs::write(full, bytes).unwrap();
}
fn open(temp: &tempfile::TempDir, config: RuntimeConfig, script: String) -> Runtime {
    Runtime::open(
        temp.path().join("session.db"),
        temp.path().join("workspace"),
        Arc::new(Script(script)),
        Model::new("fixture", "preset-workspace-data"),
        config,
    )
    .unwrap()
}
async fn prompt_once(rt: &Runtime, id: &str) -> Result<SessionView, RuntimeError> {
    tokio::time::timeout(
        Duration::from_secs(30),
        rt.prompt(id, "preset fixture", CancellationToken::new()),
    )
    .await
    .expect("prompt timed out")
}
async fn run_script(
    temp: &tempfile::TempDir,
    config: RuntimeConfig,
    script: impl Into<String>,
) -> (Runtime, String, SessionView) {
    let rt = open(temp, config, script.into());
    let id = rt.create(None).unwrap().id;
    let view = prompt_once(&rt, &id).await.expect("prompt failed");
    (rt, id, view)
}
/// An unknown outcome cancels the run, so the prompt may surface either the
/// settled session view or the cancellation error. Durable Core state is the
/// authority and is read with `Runtime::get`.
async fn run_script_outcome(
    temp: &tempfile::TempDir,
    config: RuntimeConfig,
    script: impl Into<String>,
) -> (Runtime, String, Result<SessionView, RuntimeError>) {
    let rt = open(temp, config, script.into());
    let id = rt.create(None).unwrap().id;
    let outcome = prompt_once(&rt, &id).await;
    (rt, id, outcome)
}
fn assert_reconciliation_prompt(outcome: &Result<SessionView, RuntimeError>) {
    if let Err(error) = outcome {
        assert!(
            matches!(
                error,
                RuntimeError::Worker(_)
                    | RuntimeError::Cancelled
                    | RuntimeError::NeedsReconciliation
            ),
            "unexpected reconciliation surface: {error}"
        );
    }
}
fn start(rt: &Runtime, id: &str) -> tokio::task::JoinHandle<Result<SessionView, RuntimeError>> {
    let rt = rt.clone();
    let id = id.to_string();
    tokio::spawn(async move {
        rt.prompt(&id, "preset fixture", CancellationToken::new())
            .await
    })
}
async fn pending(rt: &Runtime, id: &str) -> ApprovalRequest {
    tokio::time::timeout(Duration::from_secs(10), async {
        loop {
            if let Some(approval) = rt.get(id).unwrap().pending_approvals.first() {
                return approval.clone();
            }
            tokio::task::yield_now().await;
        }
    })
    .await
    .expect("approval did not appear")
}
fn settled(rt: &Runtime, id: &str) -> Vec<CapabilityCallRecord> {
    rt.events(id, 0, 1000)
        .unwrap()
        .into_iter()
        .filter_map(|event| match event.event {
            CoreEvent::CapabilitySettled { call } => Some(call),
            _ => None,
        })
        .collect()
}
fn completed(call: &CapabilityCallRecord) -> &Value {
    match call.outcome.as_ref() {
        Some(CapabilityOutcome::Completed { result }) => result,
        other => panic!("{} did not complete: {other:?}", call.name),
    }
}
fn known_failure(call: &CapabilityCallRecord) -> &str {
    match call.outcome.as_ref() {
        Some(CapabilityOutcome::Failed { error }) => error,
        Some(CapabilityOutcome::NotExecuted { reason }) => reason,
        other => panic!("{} was not a known failure: {other:?}", call.name),
    }
}
fn outcome(call: &CapabilityCallRecord) -> &CapabilityOutcome {
    call.outcome.as_ref().expect("settled outcome")
}
fn assert_idle(view: &SessionView) {
    assert_eq!(view.state, SessionState::Idle, "{view:?}");
    assert!(view.unresolved_capabilities.is_empty(), "{view:?}");
}

/// One uncompressed ustar entry followed by the two mandatory end blocks.
fn tar(entries: &[(&str, &[u8])]) -> Vec<u8> {
    let mut out = Vec::new();
    for (name, body) in entries {
        let mut header = [0u8; 512];
        header[..name.len()].copy_from_slice(name.as_bytes());
        header[100..108].copy_from_slice(b"0000644\0");
        header[108..116].copy_from_slice(b"0000000\0");
        header[116..124].copy_from_slice(b"0000000\0");
        header[124..136].copy_from_slice(format!("{:011o}\0", body.len()).as_bytes());
        header[136..148].copy_from_slice(b"00000000000\0");
        header[148..156].fill(b' ');
        header[156] = b'0';
        header[257..263].copy_from_slice(b"ustar\0");
        header[263..265].copy_from_slice(b"00");
        let sum: u32 = header.iter().map(|byte| u32::from(*byte)).sum();
        header[148..156].copy_from_slice(format!("{sum:06o}\0 ").as_bytes());
        out.extend_from_slice(&header);
        out.extend_from_slice(body);
        let padding = (512 - body.len() % 512) % 512;
        out.resize(out.len() + padding, 0);
    }
    out.resize(out.len() + 1024, 0);
    out
}

/// a.json "1" -> "10" and b.json absent -> "20".
fn batch_prepare_operations() -> Value {
    json!({"operations":[
        {"op":"write","path":"a.json","expected":{"kind":"sha256","sha256":HASH_EXISTING_ONE},"content":"10","encoding":"utf8","language":"json"},
        {"op":"write","path":"b.json","expected":{"kind":"absent"},"content":"20","encoding":"utf8","language":"json"}
    ]})
}
const PREPARE_SCRIPT: &str = "local p=cayw.call('fs.prepare_change_batch',{operations={ \
 {op='write',path='a.json',expected={kind='sha256',sha256='6b86b273ff34fce19d6b804eff5a3f5747ada4eaa22f1d49c01e52ddb7875b4b'},content='10',encoding='utf8',language='json'}, \
 {op='write',path='b.json',expected={kind='absent'},content='20',encoding='utf8',language='json'} }})\nreturn p";
const BLOCKED_WRITE_SCRIPT: &str =
    "return cayw.call('fs.write',{path='blocked.txt',content='blocked'})";

fn submit_script(batch_id: &str, digest: &str) -> String {
    format!(
        "local s=cayw.call('fs.submit_change_batch',{{batch_id='{batch_id}',expected_batch_digest='{digest}'}})\n\
         local g=cayw.call('fs.batch_status',{{}})\n\
         return {{submit=s,status=g}}"
    )
}
/// Creates the deterministic staging name an interrupted installation leaves
/// behind, so the next operation in the batch fails after the first effect.
fn block_second_install(root: &Path, batch_id: &str) {
    write(root, &format!(".cayw-workspace-{batch_id}-1-commit"), b"x");
}
async fn prepare_batch(temp: &tempfile::TempDir, root: &Path) -> (String, String) {
    write(root, "a.json", b"1");
    let mut cfg = config();
    allow(
        &mut cfg,
        "fs.prepare_change_batch",
        batch_prepare_operations(),
    );
    let (rt, id, view) = run_script(temp, cfg, PREPARE_SCRIPT).await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1, "{calls:?}");
    let result = completed(&calls[0]);
    assert_eq!(result["status"], "prepared");
    assert_eq!(result["user_files_changed"], false);
    let batch_id = result["batch_id"].as_str().unwrap().to_string();
    let digest = result["batch_digest"].as_str().unwrap().to_string();
    drop(rt);
    (batch_id, digest)
}

#[tokio::test]
async fn host_write_patch_tree_and_committed_batch_are_real_runtime_paths() {
    let temp = setup();
    let mut cfg = config();
    allow(
        &mut cfg,
        "fs.write",
        json!({"path":"a.txt","content":"one"}),
    );
    allow(
        &mut cfg,
        "fs.write",
        json!({"path":"a.txt","content":"two","overwrite":true,"expected_sha256":HASH_ONE}),
    );
    allow(
        &mut cfg,
        "fs.patch",
        json!({"path":"a.txt","old":"two","new":"three","expected_sha256":HASH_TWO}),
    );
    allow(&mut cfg, "fs.tree", json!({"path":".","max_entries":16}));
    let script = "local w=cayw.call('fs.write',{path='a.txt',content='one'})\n\
        local o=cayw.call('fs.write',{path='a.txt',content='two',overwrite=true,expected_sha256='7692c3ad3540bb803c020b3aee66cd8887123234ea0c6e7143c0add73ff431ed'})\n\
        local p=cayw.call('fs.patch',{path='a.txt',old='two',new='three',expected_sha256='3fc4ccfe745870e2c0d99f71f30ff0656c8dedd41cc1d7d3d376b0dbe685e2f3'})\n\
        local t=cayw.call('fs.tree',{path='.',max_entries=16})\n\
        return {write=w,overwrite=o,patch=p,tree=t}";
    let (rt, id, view) = run_script(&temp, cfg, script).await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 4, "{calls:?}");
    assert!(
        calls
            .iter()
            .all(|call| call.stage == CapabilityStage::Settled)
    );
    assert_eq!(completed(&calls[0])["sha256"], HASH_ONE);
    assert_eq!(completed(&calls[1])["sha256"], HASH_TWO);
    assert_eq!(completed(&calls[2])["sha256"], HASH_THREE);
    let entries = completed(&calls[3])["entries"].as_array().unwrap();
    assert!(entries.iter().any(|entry| entry["path"] == "a.txt"
        && entry["kind"] == "file"
        && entry["sha256"] == HASH_THREE));
    assert_eq!(
        std::fs::read_to_string(temp.path().join("workspace/a.txt")).unwrap(),
        "three"
    );
    drop(rt);

    // Prepare and submit are separate real Runtimes. The exact submit scope is
    // only knowable after prepare generated the ID and digest.
    let (batch_id, digest) = prepare_batch(&temp, &temp.path().join("workspace")).await;
    let mut cfg = config();
    allow(
        &mut cfg,
        "fs.submit_change_batch",
        json!({"batch_id":batch_id,"expected_batch_digest":digest}),
    );
    allow(&mut cfg, "fs.batch_status", json!({}));
    let (rt, id, view) = run_script(&temp, cfg, submit_script(&batch_id, &digest)).await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 2, "{calls:?}");
    let submitted = completed(&calls[0]);
    assert_eq!(submitted["status"], "committed");
    assert_eq!(submitted["outcome_unknown"], false);
    let status = completed(&calls[1]);
    assert_eq!(status["batches"][0]["status"], "committed");
    assert_eq!(status["batches"][0]["outcome_unknown"], false);
    assert_eq!(status["batches"][0]["recorded_installed"], 2);
    assert_eq!(
        std::fs::read_to_string(temp.path().join("workspace/a.json")).unwrap(),
        "10"
    );
    assert_eq!(
        std::fs::read_to_string(temp.path().join("workspace/b.json")).unwrap(),
        "20"
    );
}

#[tokio::test]
async fn invalid_arguments_escape_and_tree_bound_fail_before_effect() {
    let temp = setup();
    write(&temp.path().join("workspace"), "keep.txt", b"keep");

    // Passes the public catalog schema (no conditional schema keyword), then the
    // Host rejects the overwrite/expected_sha256 coupling as a known failure.
    let mut cfg = config();
    allow(
        &mut cfg,
        "fs.write",
        json!({"path":"x.txt","content":"one","expected_sha256":HASH_ONE}),
    );
    let (rt, id, view) = run_script(
        &temp,
        cfg,
        "return cayw.call('fs.write',{path='x.txt',content='one',expected_sha256='7692c3ad3540bb803c020b3aee66cd8887123234ea0c6e7143c0add73ff431ed'})",
    )
    .await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1, "{calls:?}");
    assert!(
        known_failure(&calls[0]).contains("expected_sha256 requires overwrite=true"),
        "{:?}",
        calls[0].outcome
    );
    assert!(!temp.path().join("workspace/x.txt").exists());
    drop(rt);

    let mut cfg = config();
    allow(&mut cfg, "fs.read", json!({"path":"../escape.txt"}));
    let (rt, id, view) = run_script(
        &temp,
        cfg,
        "return cayw.call('fs.read',{path='../escape.txt'})",
    )
    .await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1);
    assert!(known_failure(&calls[0]).contains("forbidden or reserved"));
    assert_eq!(
        std::fs::read_to_string(temp.path().join("escape.txt"))
            .unwrap_err()
            .kind(),
        std::io::ErrorKind::NotFound
    );
    drop(rt);

    let mut cfg = config();
    let mut limits = cfg.host.workspace.expect("workspace catalog");
    limits.max_tree_entries = 2;
    cfg.host.workspace = Some(limits);
    allow(&mut cfg, "fs.tree", json!({"path":".","max_entries":10}));
    let (rt, id, view) = run_script(
        &temp,
        cfg,
        "return cayw.call('fs.tree',{path='.',max_entries=10})",
    )
    .await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1);
    assert!(known_failure(&calls[0]).contains("tree entry bound"));
}

#[tokio::test]
async fn write_byte_limit_and_host_call_budget_are_known_failures() {
    let temp = setup();
    let mut cfg = config();
    cfg.host.max_file_bytes = 8;
    allow(
        &mut cfg,
        "fs.write",
        json!({"path":"big.txt","content":"123456789"}),
    );
    let (rt, id, view) = run_script(
        &temp,
        cfg,
        "return cayw.call('fs.write',{path='big.txt',content='123456789'})",
    )
    .await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1);
    assert!(known_failure(&calls[0]).contains("byte limit"));
    assert!(!temp.path().join("workspace/big.txt").exists());
    drop(rt);

    let temp = setup();
    let mut cfg = config();
    cfg.host.max_calls = 1;
    allow(
        &mut cfg,
        "fs.write",
        json!({"path":"a.txt","content":"one"}),
    );
    allow(
        &mut cfg,
        "fs.write",
        json!({"path":"b.txt","content":"two"}),
    );
    let (rt, id, view) = run_script(
        &temp,
        cfg,
        "local a=cayw.call('fs.write',{path='a.txt',content='one'})\n\
         local b=cayw.call('fs.write',{path='b.txt',content='two'})\n\
         return {a=a,b=b}",
    )
    .await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 2, "{calls:?}");
    assert_eq!(completed(&calls[0])["sha256"], HASH_ONE);
    assert!(known_failure(&calls[1]).contains("budget"));
    assert!(temp.path().join("workspace/a.txt").exists());
    assert!(!temp.path().join("workspace/b.txt").exists());
}

#[tokio::test]
async fn denied_and_cancelled_write_never_touch_the_workspace() {
    let temp = setup();
    let rt = open(
        &temp,
        config(),
        "return cayw.call('fs.write',{path='denied.txt',content='denied'})".into(),
    );
    let id = rt.create(None).unwrap().id;
    let run = start(&rt, &id);
    let approval = pending(&rt, &id).await;
    rt.approve(&id, &approval.id, ApprovalChoice::Deny, "preset-test")
        .unwrap();
    let view = run.await.unwrap().unwrap();
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1);
    assert!(matches!(
        outcome(&calls[0]),
        CapabilityOutcome::NotExecuted { .. }
    ));
    assert!(!temp.path().join("workspace/denied.txt").exists());
    drop(rt);

    let temp = setup();
    let rt = open(
        &temp,
        config(),
        "return cayw.call('fs.write',{path='cancelled.txt',content='cancelled'})".into(),
    );
    let id = rt.create(None).unwrap().id;
    let run = start(&rt, &id);
    let approval = pending(&rt, &id).await;
    let original = rt.task(&approval.input.task_id).unwrap();
    assert!(rt.cancel(&original.cancel_target()).unwrap());
    let result = run.await.unwrap();
    if let Err(error) = &result {
        assert!(
            matches!(error, RuntimeError::Cancelled | RuntimeError::Worker(_)),
            "unexpected cancellation surface: {error}"
        );
    }
    let view = rt.get(&id).unwrap();
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1);
    assert!(matches!(
        outcome(&calls[0]),
        CapabilityOutcome::NotExecuted { .. }
    ));
    assert!(view.pending_approvals.is_empty());
    let task = rt.tasks(&id).unwrap().remove(0);
    assert_eq!(task.state, TaskState::Cancelled);
    assert!(!temp.path().join("workspace/cancelled.txt").exists());
}

#[tokio::test]
async fn interrupted_change_batch_recovers_through_a_fresh_runtime() {
    let temp = setup();
    let workspace = temp.path().join("workspace");
    let (batch_id, digest) = prepare_batch(&temp, &workspace).await;
    block_second_install(&workspace, &batch_id);

    let mut cfg = config();
    allow(
        &mut cfg,
        "fs.submit_change_batch",
        json!({"batch_id":batch_id,"expected_batch_digest":digest}),
    );
    let (submit_rt, submit_id, prompt) = run_script_outcome(
        &temp,
        cfg,
        format!(
            "return cayw.call('fs.submit_change_batch',{{batch_id='{batch_id}',expected_batch_digest='{digest}'}})"
        ),
    )
    .await;
    assert_reconciliation_prompt(&prompt);
    let view = submit_rt.get(&submit_id).unwrap();
    assert_eq!(view.state, SessionState::NeedsReconciliation, "{view:?}");
    assert_eq!(view.unresolved_capabilities.len(), 1, "{view:?}");
    let original = view.unresolved_capabilities[0].clone();
    let calls = settled(&submit_rt, &submit_id);
    assert_eq!(calls.len(), 1, "{calls:?}");
    assert!(matches!(
        outcome(&calls[0]),
        CapabilityOutcome::OutcomeUnknown { .. }
    ));
    assert_eq!(
        std::fs::read_to_string(workspace.join("a.json")).unwrap(),
        "10"
    );
    assert!(!workspace.join("b.json").exists());
    drop(submit_rt);

    // The Host fence refuses a second owner's mutation until the original
    // unknown call is reconciled from its own durable evidence.
    let mut fence = config();
    allow(
        &mut fence,
        "fs.write",
        json!({"path":"blocked.txt","content":"blocked"}),
    );
    let (fence, fence_id, fence_prompt) =
        run_script_outcome(&temp, fence, BLOCKED_WRITE_SCRIPT).await;
    assert_reconciliation_prompt(&fence_prompt);
    let fence_view = fence.get(&fence_id).unwrap();
    assert_eq!(
        fence_view.state,
        SessionState::NeedsReconciliation,
        "{fence_view:?}"
    );
    let calls = settled(&fence, &fence_id);
    assert_eq!(calls.len(), 1, "{calls:?}");
    assert!(matches!(
        outcome(&calls[0]),
        CapabilityOutcome::OutcomeUnknown { error }
            if error.contains("original owner recovery")
    ));
    assert!(!workspace.join("blocked.txt").exists());
    drop(fence);

    // Read-only journal evidence remains available before reconciliation.
    let mut cfg = config();
    allow(&mut cfg, "fs.batch_status", json!({}));
    let (status_rt, status_id, status_view) =
        run_script(&temp, cfg, "return cayw.call('fs.batch_status',{})").await;
    assert_idle(&status_view);
    let calls = settled(&status_rt, &status_id);
    assert_eq!(calls.len(), 1, "{calls:?}");
    let status = completed(&calls[0]);
    assert_eq!(status["batches"][0]["outcome_unknown"], true);
    assert_eq!(status["batches"][0]["recorded_installed"], 1);
    drop(status_rt);

    // Host authority: stop the original owner, then reconcile the exact
    // capability from the journal evidence. This also clears the Host fence.
    assert_eq!(original.name, "fs.submit_change_batch");
    assert_eq!(
        original.arguments,
        json!({"batch_id":batch_id,"expected_batch_digest":digest})
    );
    let receipt = CapabilityReconciliation {
        key: original.key.clone(),
        expected: (&original).into(),
        actor: "fixture-host".into(),
        evidence: format!(
            "fs.batch_status observed change batch {batch_id} outcome_unknown with recorded_installed=1; a.json contains 10 and b.json is absent"
        ),
        outcome: CapabilityOutcome::Failed {
            error: "change batch submit was interrupted after 1 of 2 installations; explicit rollback required".into(),
        },
        external_provenance: original.external_provenance.clone(),
    };
    let mut settings = config();
    settings.reconciliation_verifier = Some(Arc::new(InspectedBatchReceipt(receipt.clone())));
    let reconcile_rt = open(&temp, settings, "return nil".into());
    let recovered = reconcile_rt.recover(&submit_id).unwrap();
    assert_eq!(
        recovered.state,
        SessionState::NeedsReconciliation,
        "{recovered:?}"
    );
    let mut forged = receipt.clone();
    forged.expected.task_id = "replacement-task".into();
    assert!(
        reconcile_rt
            .reconcile_capability(&submit_id, forged)
            .is_err()
    );
    let reconciled = reconcile_rt
        .reconcile_capability(&submit_id, receipt)
        .unwrap();
    assert_idle(&reconciled);
    drop(reconcile_rt);

    // The fence is cleared, so the journal rollback now runs through a fresh
    // Runtime and the real Host path.
    let mut recovery = config();
    allow(&mut recovery, "fs.batch_status", json!({}));
    allow(
        &mut recovery,
        "fs.recover_change_batch",
        json!({"batch_id":batch_id,"expected_batch_digest":digest,"action":"rollback"}),
    );
    allow(
        &mut recovery,
        "fs.write",
        json!({"path":"after.txt","content":"ok"}),
    );
    let script = format!(
        "local s=cayw.call('fs.batch_status',{{}})\n\
         local r=cayw.call('fs.recover_change_batch',{{batch_id='{batch_id}',expected_batch_digest='{digest}',action='rollback'}})\n\
         local w=cayw.call('fs.write',{{path='after.txt',content='ok'}})\n\
         return {{status=s,recovered=r,write=w}}"
    );
    let (recovery, recovery_id, recovery_view) = run_script(&temp, recovery, script).await;
    assert_idle(&recovery_view);
    let calls = settled(&recovery, &recovery_id);
    assert_eq!(calls.len(), 3, "{calls:?}");
    let status = completed(&calls[0]);
    assert_eq!(status["batches"][0]["outcome_unknown"], true);
    assert_eq!(status["batches"][0]["recorded_installed"], 1);
    let recovered = completed(&calls[1]);
    assert_eq!(recovered["status"], "rolled_back");
    assert_eq!(recovered["outcome_unknown"], false);
    assert_eq!(
        std::fs::read_to_string(workspace.join("a.json")).unwrap(),
        "1"
    );
    assert!(!workspace.join("b.json").exists());
    assert_eq!(
        std::fs::read_to_string(workspace.join("after.txt")).unwrap(),
        "ok"
    );
}

#[tokio::test]
async fn third_party_change_blocks_batch_recovery_through_host() {
    let temp = setup();
    let workspace = temp.path().join("workspace");
    let (batch_id, digest) = prepare_batch(&temp, &workspace).await;
    block_second_install(&workspace, &batch_id);

    let mut cfg = config();
    allow(
        &mut cfg,
        "fs.submit_change_batch",
        json!({"batch_id":batch_id,"expected_batch_digest":digest}),
    );
    let (rt, id, prompt) = run_script_outcome(
        &temp,
        cfg,
        format!(
            "return cayw.call('fs.submit_change_batch',{{batch_id='{batch_id}',expected_batch_digest='{digest}'}})"
        ),
    )
    .await;
    assert_reconciliation_prompt(&prompt);
    let view = rt.get(&id).unwrap();
    assert_eq!(view.state, SessionState::NeedsReconciliation, "{view:?}");
    let original = view.unresolved_capabilities[0].clone();
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1, "{calls:?}");
    assert!(matches!(
        outcome(&calls[0]),
        CapabilityOutcome::OutcomeUnknown { .. }
    ));
    assert_eq!(
        std::fs::read_to_string(workspace.join("a.json")).unwrap(),
        "10"
    );
    assert!(!workspace.join("b.json").exists());
    write(&workspace, "b.json", b"third party");
    drop(rt);

    let mut cfg = config();
    allow(&mut cfg, "fs.batch_status", json!({}));
    let (status_rt, status_id, status_view) =
        run_script(&temp, cfg, "return cayw.call('fs.batch_status',{})").await;
    assert_idle(&status_view);
    let calls = settled(&status_rt, &status_id);
    assert_eq!(calls.len(), 1, "{calls:?}");
    let status = completed(&calls[0]);
    assert_eq!(status["batches"][0]["paths"][1]["matches"], "third_party");
    drop(status_rt);

    assert_eq!(original.name, "fs.submit_change_batch");
    assert_eq!(
        original.arguments,
        json!({"batch_id":batch_id,"expected_batch_digest":digest})
    );
    assert_eq!(
        std::fs::read_to_string(workspace.join("b.json")).unwrap(),
        "third party"
    );
    let receipt = CapabilityReconciliation {
        key: original.key.clone(),
        expected: (&original).into(),
        actor: "fixture-host".into(),
        evidence: format!(
            "fs.batch_status observed change batch {batch_id} outcome_unknown with recorded_installed=1; b.json now differs from both recorded states"
        ),
        outcome: CapabilityOutcome::Failed {
            error:
                "change batch submit was interrupted; recovery is blocked by a third-party change"
                    .into(),
        },
        external_provenance: original.external_provenance.clone(),
    };
    let mut settings = config();
    settings.reconciliation_verifier = Some(Arc::new(InspectedBatchReceipt(receipt.clone())));
    let reconcile_rt = open(&temp, settings, "return nil".into());
    reconcile_rt.recover(&id).unwrap();
    let mut forged = receipt.clone();
    forged.actor = "untrusted-caller".into();
    assert!(reconcile_rt.reconcile_capability(&id, forged).is_err());
    let reconciled = reconcile_rt.reconcile_capability(&id, receipt).unwrap();
    assert_idle(&reconciled);
    drop(reconcile_rt);

    let mut cfg = config();
    allow(
        &mut cfg,
        "fs.recover_change_batch",
        json!({"batch_id":batch_id,"expected_batch_digest":digest,"action":"rollback"}),
    );
    let script = format!(
        "return cayw.call('fs.recover_change_batch',{{batch_id='{batch_id}',expected_batch_digest='{digest}',action='rollback'}})"
    );
    let (rt, id, prompt) = run_script_outcome(&temp, cfg, script).await;
    assert_reconciliation_prompt(&prompt);
    let view = rt.get(&id).unwrap();
    assert_eq!(view.state, SessionState::NeedsReconciliation, "{view:?}");
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1, "{calls:?}");
    assert!(matches!(
        outcome(&calls[0]),
        CapabilityOutcome::OutcomeUnknown { error }
            if error.contains("third-party change blocks recovery")
    ));
    assert_eq!(
        std::fs::read_to_string(workspace.join("a.json")).unwrap(),
        "10"
    );
    assert_eq!(
        std::fs::read_to_string(workspace.join("b.json")).unwrap(),
        "third party"
    );
    drop(rt);

    // The failed recovery changed no file and left the journal unknown.
    let mut cfg = config();
    allow(&mut cfg, "fs.batch_status", json!({}));
    let (status_rt, status_id, status_view) =
        run_script(&temp, cfg, "return cayw.call('fs.batch_status',{})").await;
    assert_idle(&status_view);
    let calls = settled(&status_rt, &status_id);
    assert_eq!(calls.len(), 1, "{calls:?}");
    let status = completed(&calls[0]);
    assert_eq!(status["batches"][0]["outcome_unknown"], true);
    assert_eq!(status["batches"][0]["recorded_installed"], 1);
    assert_eq!(status["batches"][0]["paths"][1]["matches"], "third_party");
}

#[tokio::test]
async fn grep_glob_outline_and_diff_hunks_return_host_results() {
    let temp = setup();
    let workspace = temp.path().join("workspace");
    write(&workspace, "src/a.txt", b"alpha\nbeta\nalpha\n");
    write(&workspace, "lib.rs", b"pub fn hello() {}\n");
    let mut cfg = config();
    allow(&mut cfg, "fs.grep", json!({"path":"src","pattern":"alpha"}));
    allow(
        &mut cfg,
        "fs.glob",
        json!({"path":".","pattern":"**/*.txt"}),
    );
    allow(
        &mut cfg,
        "code.outline",
        json!({"path":"lib.rs","language":"rust"}),
    );
    allow(
        &mut cfg,
        "code.diff_hunks",
        json!({"diff":"--- a/a.txt\n+++ b/a.txt\n@@ -1 +1 @@\n-alpha\n+beta\n"}),
    );
    let script = "local g=cayw.call('fs.grep',{path='src',pattern='alpha'})\n\
        local f=cayw.call('fs.glob',{path='.',pattern='**/*.txt'})\n\
        local o=cayw.call('code.outline',{path='lib.rs',language='rust'})\n\
        local d=cayw.call('code.diff_hunks',{diff='--- a/a.txt\\n+++ b/a.txt\\n@@ -1 +1 @@\\n-alpha\\n+beta\\n'})\n\
        return {grep=g,glob=f,outline=o,diff=d}";
    let (rt, id, view) = run_script(&temp, cfg, script).await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 4, "{calls:?}");
    let grep = completed(&calls[0]);
    assert_eq!(grep["matches"].as_array().unwrap().len(), 2);
    assert!(
        grep["matches"]
            .as_array()
            .unwrap()
            .iter()
            .all(|m| m["path"] == "src/a.txt" && m["text"] == "alpha")
    );
    assert_eq!(grep["scan_complete"], true);
    let glob = completed(&calls[1]);
    assert_eq!(glob["paths"], json!(["src/a.txt"]));
    assert_eq!(glob["truncated"], false);
    let outline = completed(&calls[2]);
    assert!(
        outline["symbols"]
            .as_array()
            .unwrap()
            .iter()
            .any(|symbol| symbol["name"] == "hello" && symbol["kind"] == "function")
    );
    let diff = completed(&calls[3]);
    assert_eq!(diff["total_hunks"], 1);
    assert_eq!(diff["hunks"][0]["old_path"], "a.txt");
    assert_eq!(diff["validated_complete"], true);
}

