#[tokio::test]
async fn data_formats_query_transform_diff_hash_and_codecs_round_trip() {
    let temp = setup();
    let mut cfg = config();
    for (name, args) in [
        (
            "data.parse",
            json!({"format":"json","text":"{\"a\":1,\"b\":[true,null]}"}),
        ),
        (
            "data.parse",
            json!({"format":"toml","text":"name = \"cayw\"\ncount = 2\n"}),
        ),
        (
            "data.parse",
            json!({"format":"yaml","text":"a: 1\nb: two\n"}),
        ),
        (
            "data.parse",
            json!({"format":"xml","text":"<root><item>x</item></root>"}),
        ),
        (
            "data.parse",
            json!({"format":"csv","text":"id,note\n1,hello\n2,world\n"}),
        ),
        (
            "data.serialize",
            json!({"format":"csv","value":{"header":["id","note"],"rows":[["1","x"]]}}),
        ),
        (
            "data.query",
            json!({"value":{"a":{"b":2}},"pointer":"/a/b"}),
        ),
        (
            "data.transform",
            json!({"value":{"a":1,"b":2,"c":3},"operation":"select_fields","fields":["a","c"]}),
        ),
        ("text.diff", json!({"before":"a\nb\n","after":"a\nc\n"})),
        (
            "hash.digest",
            json!({"algorithm":"sha256","input":{"kind":"utf8","value":"abc"}}),
        ),
        (
            "hash.digest",
            json!({"algorithm":"blake3","input":{"kind":"utf8","value":"abc"}}),
        ),
        (
            "codec.encode",
            json!({"encoding":"base64","input":{"kind":"bytes","value":[97,98,99]}}),
        ),
        (
            "codec.encode",
            json!({"encoding":"hex","input":{"kind":"utf8","value":"abc"}}),
        ),
        (
            "codec.decode",
            json!({"encoding":"base64","text":"YWJj","output":"utf8"}),
        ),
        (
            "codec.decode",
            json!({"encoding":"hex","text":"616263","output":"bytes"}),
        ),
    ] {
        allow(&mut cfg, name, args);
    }
    let script = "local j=cayw.call('data.parse',{format='json',text='{\"a\":1,\"b\":[true,null]}'})\n\
        local t=cayw.call('data.parse',{format='toml',text='name = \"cayw\"\\ncount = 2\\n'})\n\
        local y=cayw.call('data.parse',{format='yaml',text='a: 1\\nb: two\\n'})\n\
        local x=cayw.call('data.parse',{format='xml',text='<root><item>x</item></root>'})\n\
        local c=cayw.call('data.parse',{format='csv',text='id,note\\n1,hello\\n2,world\\n'})\n\
        local s=cayw.call('data.serialize',{format='csv',value={header={'id','note'},rows={{'1','x'}}}})\n\
        local q=cayw.call('data.query',{value={a={b=2}},pointer='/a/b'})\n\
        local r=cayw.call('data.transform',{value={a=1,b=2,c=3},operation='select_fields',fields={'a','c'}})\n\
        local d=cayw.call('text.diff',{before='a\\nb\\n',after='a\\nc\\n'})\n\
        local h=cayw.call('hash.digest',{algorithm='sha256',input={kind='utf8',value='abc'}})\n\
        local k=cayw.call('hash.digest',{algorithm='blake3',input={kind='utf8',value='abc'}})\n\
        local e=cayw.call('codec.encode',{encoding='base64',input={kind='bytes',value={97,98,99}}})\n\
        local f=cayw.call('codec.encode',{encoding='hex',input={kind='utf8',value='abc'}})\n\
        local u=cayw.call('codec.decode',{encoding='base64',text='YWJj',output='utf8'})\n\
        local v=cayw.call('codec.decode',{encoding='hex',text='616263',output='bytes'})\n\
        return {json=j,toml=t,yaml=y,xml=x,csv=c,serialized=s,query=q,transform=r,diff=d,sha=h,blake=k,base64=e,hex=f,decoded=u,bytes=v}";
    let (rt, id, view) = run_script(&temp, cfg, script).await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 15, "{calls:?}");
    assert!(
        calls
            .iter()
            .all(|call| call.stage == CapabilityStage::Settled)
    );
    let json = completed(&calls[0]);
    assert_eq!(json["value"]["a"], json!(1));
    assert_eq!(json["value"]["b"], json!([true, null]));
    assert_eq!(completed(&calls[1])["value"]["name"], "cayw");
    assert_eq!(completed(&calls[1])["value"]["count"], json!(2));
    assert_eq!(completed(&calls[2])["value"]["b"], "two");
    assert_eq!(completed(&calls[3])["value"]["name"], "root");
    let csv = completed(&calls[4]);
    assert_eq!(csv["value"]["header"], json!(["id", "note"]));
    assert_eq!(csv["value"]["rows"][1], json!(["2", "world"]));
    assert_eq!(
        completed(&calls[5])["text"],
        "\"id\",\"note\"\n\"1\",\"x\"\n"
    );
    assert_eq!(completed(&calls[6])["value"], json!(2));
    assert_eq!(completed(&calls[7])["value"], json!({"a":1,"c":3}));
    let diff = completed(&calls[8])["diff"].as_str().unwrap();
    assert!(diff.contains("-b\n") && diff.contains("+c\n"), "{diff}");
    assert_eq!(completed(&calls[9])["hex"], SHA256_ABC);
    assert_eq!(completed(&calls[10])["hex"], BLAKE3_ABC);
    assert_eq!(completed(&calls[11])["text"], "YWJj");
    assert_eq!(completed(&calls[12])["text"], "616263");
    assert_eq!(completed(&calls[13])["text"], "abc");
    assert_eq!(completed(&calls[14])["bytes"], json!([97, 98, 99]));
}

#[tokio::test]
async fn archive_list_and_read_use_the_workspace_host_path() {
    let temp = setup();
    let workspace = temp.path().join("workspace");
    std::fs::write(
        workspace.join("bundle.tar"),
        tar(&[("note.txt", TAR_BODY.as_bytes())]),
    )
    .unwrap();
    let mut cfg = config();
    allow(
        &mut cfg,
        "archive.list",
        json!({"path":"bundle.tar","format":"tar"}),
    );
    allow(
        &mut cfg,
        "archive.read",
        json!({"path":"bundle.tar","format":"tar","entry":"note.txt"}),
    );
    let (rt, id, view) = run_script(
        &temp,
        cfg,
        "local l=cayw.call('archive.list',{path='bundle.tar',format='tar'})\n\
         local r=cayw.call('archive.read',{path='bundle.tar',format='tar',entry='note.txt'})\n\
         return {list=l,read=r}",
    )
    .await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 2, "{calls:?}");
    let list = completed(&calls[0]);
    assert_eq!(list["entries"][0]["path"], "note.txt");
    assert_eq!(list["entries"][0]["kind"], "file");
    assert_eq!(list["entries"][0]["bytes"], json!(TAR_BODY.len()));
    let read = completed(&calls[1]);
    assert_eq!(read["entry"], "note.txt");
    assert_eq!(read["data"]["encoding"], "utf8");
    assert_eq!(read["data"]["content"], TAR_BODY);
    assert_eq!(read["data"]["bytes"], json!(TAR_BODY.len()));
    drop(rt);

    let mut cfg = config();
    allow(
        &mut cfg,
        "archive.read",
        json!({"path":"bundle.tar","format":"tar","entry":"../escape"}),
    );
    let (rt, id, view) = run_script(
        &temp,
        cfg,
        "return cayw.call('archive.read',{path='bundle.tar',format='tar',entry='../escape'})",
    )
    .await;
    assert_idle(&view);
    let calls = settled(&rt, &id);
    assert_eq!(calls.len(), 1);
    assert!(known_failure(&calls[0]).contains("forbidden or reserved"));
}

